package com.echoportal

import android.content.Context
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.media.MediaPlayer
import android.net.Uri
import android.util.Log
import org.json.JSONObject
import kotlin.math.abs
import kotlin.math.hypot

/**
 * Jarvis: shows the assistant's thinking, tool steps, confirmation prompt and final answer.
 * Voice input still happens on the Voice face; saying "Jarvis" or choosing the Jarvis target
 * routes the transcript here. Spoken output is a WAV generated by the PC and served at /media/.
 */
class AssistantFace(ctx: Context) : Face(ctx) {
    override val id = "assistant"
    override val name = "Jarvis"
    override val color = Color.parseColor("#B39DDB")
    override val channels = setOf("assistant")

    var mediaBase: String? = null
    var token: String = ""
    /** Set by the activity: id and label of this Spot, included in outgoing assistant ops. */
    var deviceId: String = ""
    var deviceName: String = ""

    private data class Step(val name: String, val done: Boolean)

    private var status = "Say \"Jarvis\" then speak, or open the Voice face and pick Jarvis."
    private var prompt = ""
    private var reply = ""
    private var steps = emptyList<Step>()
    private var confirmToken = ""
    private var confirmText = ""
    private var confirmAudioPath: String? = null
    private var streamToken = ""
    private var audioPath: String? = null
    private var audioSegments = emptyList<String>()  // full streamed answer, for replay
    private var streamedAudio = false                 // segment events already own playback
    private var player: MediaPlayer? = null
    private val pendingClips = mutableListOf<String>()  // queued sentence clips

    override fun onHide() { resetAudio() }

    /** Assistant op payload with the device id attached when known (older hubs ignore it). */
    private fun op(op: String, extra: (JSONObject) -> Unit = {}): JSONObject =
        JSONObject().put("op", op).also { data ->
            if (deviceId.isNotEmpty()) data.put("device", deviceId)
            extra(data)
        }

    /** Direct question to the PC assistant; kept separate from the voice-driven ask path. */
    fun ask(text: String) {
        send(JSONObject().put("ch", "assistant").put("data", op("ask") { it.put("text", text) }))
    }

    override fun onEvent(channel: String, data: JSONObject) {
        // With more than one Spot attached, ignore turns that belong to another device.
        val eventDevice = data.optString("device")
        if (eventDevice.isNotEmpty() && deviceId.isNotEmpty() && eventDevice != deviceId) return
        when (data.optString("op")) {
            "status" -> {
                val ready = data.optBoolean("ready")
                status = if (ready) "Ready · ${data.optString("backend", "assistant")}"
                         else "Assistant backend unavailable - check the PC config"
            }
            "prompt", "thinking" -> {
                val asked = data.optString("text")
                if (asked.isNotEmpty()) prompt = asked.take(140)
                reply = ""
                steps = emptyList()
                confirmToken = ""
                confirmText = ""
                confirmAudioPath = null
                streamToken = ""
                audioPath = null
                audioSegments = emptyList()
                streamedAudio = false
                resetAudio()
                status = "Thinking…"
                invalidate()
            }
            "stream" -> {
                val token = data.optString("token")
                // A tool round gives the next model call a new token; keep following this turn.
                if (token.isNotEmpty()) streamToken = token
                reply = data.optString("text").take(MAX_REPLY_CHARS)
                confirmToken = ""
                confirmText = ""
                audioPath = null
                status = "Writing…"
                invalidate()
            }
            "speak" -> {
                val token = data.optString("token")
                if (token.isNotEmpty()) streamToken = token
                status = "Speaking…"   // progress hint only; audio arrives as segment events
                invalidate()
            }
            "audio" -> {
                if (audioPath != null) return   // a full reply clip already won
                val token = data.optString("token")
                if (token.isNotEmpty()) streamToken = token
                val path = data.optString("audio").ifEmpty { data.optString("path") }
                if (path.isNotEmpty()) {
                    if (data.optBoolean("segment", true)) {
                        audioSegments = audioSegments + path
                        streamedAudio = true
                        enqueueClip(path)
                    } else play(path)
                }
            }
            "stream_reset" -> {
                // A provider failed after emitting partial speech; discard that attempt's clips.
                streamToken = data.optString("token")
                audioSegments = emptyList()
                streamedAudio = false
                audioPath = null
                resetAudio()
                invalidate()
            }
            "tool" -> {
                val name = data.optString("text")
                if (name.isNotEmpty()) steps = steps + Step(name.take(24), false)
                status = "Using $name…"
                invalidate()
            }
            "confirm" -> {
                confirmToken = data.optString("token")
                confirmText = data.optString("text").take(180)
                confirmAudioPath = data.optString("audio").ifEmpty { null }
                status = "Needs your approval"
                invalidate()
                confirmAudioPath?.let { play(it) }
            }
            "reply" -> {
                reply = data.optString("text").take(MAX_REPLY_CHARS)
                confirmToken = ""
                confirmText = ""
                confirmAudioPath = null
                streamToken = ""
                status = ""
                steps = steps.map { it.copy(done = true) }
                val clips = data.optJSONArray("audio_segments")
                val segments = if (clips == null) emptyList() else
                    (0 until clips.length()).map { clips.optString(it) }.filter { it.isNotEmpty() }
                if (segments.isNotEmpty()) {
                    // Segment events already started this queue. Calling play() here would reset
                    // it and replay only the first sentence.
                    audioSegments = segments
                    streamedAudio = true
                    audioPath = segments.first()
                } else {
                    audioSegments = emptyList()
                    streamedAudio = false
                    audioPath = data.optString("audio").ifEmpty { null }
                    audioPath?.let { play(it) }
                }
                invalidate()
            }
            "cancelled" -> {
                streamToken = ""
                confirmToken = ""
                confirmAudioPath = null
                audioSegments = emptyList()
                streamedAudio = false
                audioPath = null
                resetAudio()
                status = "Cancelled."
                invalidate()
            }
            "error" -> {
                status = data.optString("text", "Assistant error").take(160)
                confirmToken = ""
                confirmAudioPath = null
                streamToken = ""
                invalidate()
            }
        }
    }

    override fun preview(): String = when {
        confirmToken.isNotEmpty() -> "approval needed"
        streamToken.isNotEmpty() -> "writing…"
        reply.isNotEmpty() -> reply.take(28)
        else -> "Jarvis · ask me anything"
    }

    override fun bgLevel(page: Int): Int = 2

    // ---- audio -----------------------------------------------------------------------------
    /** Stop and release the current player only. */
    private fun stopAudio() {
        try { player?.stop() } catch (_: Exception) {}
        player?.release()
        player = null
    }

    /** Drop queued sentences and stop playback (new turn, cancel, hide, barge-in). */
    fun resetAudio() {
        pendingClips.clear()
        stopAudio()
    }

    /** User started talking: flush speech and cancel the in-flight turn so no more clips arrive. */
    fun bargeIn() {
        val token = streamToken
        resetAudio()
        if (token.isNotEmpty()) {
            send(JSONObject().put("ch", "assistant")
                .put("data", op("cancel") { it.put("token", token) }))
            streamToken = ""
        }
        status = "Listening…"
        invalidate()
    }

    /** Start one clip; completion or error releases it and advances the queue. */
    private fun startClip(path: String) {
        val base = mediaBase ?: return
        val url = base + "/media/" + path +
            (if (token.isEmpty()) "" else "?token=" + Uri.encode(token))
        try {
            player = MediaPlayer().apply {
                setDataSource(url)
                setOnCompletionListener { clipFinished() }
                setOnErrorListener { _, _, _ -> clipFinished(); true }
                prepareAsync()
                setOnPreparedListener { it.start() }
            }
        } catch (e: Exception) {
            Log.w(TAG, "reply audio failed: ${e.message}")
            clipFinished()
        }
    }

    /** Release the finished player and play the next queued sentence, if any. */
    private fun clipFinished() {
        stopAudio()
        if (pendingClips.isNotEmpty()) startClip(pendingClips.removeAt(0))
    }

    /** Play a single full-reply clip; replaces any queued sentences. */
    private fun play(path: String) {
        if (mediaBase == null) return
        resetAudio()
        startClip(path)
    }

    /** Tap-to-replay: streamed answers replay every sentence, not just the first clip. */
    private fun replayAudio() {
        if (mediaBase == null) return
        if (audioSegments.isNotEmpty()) {
            resetAudio()
            pendingClips.addAll(audioSegments)
            if (pendingClips.isNotEmpty()) startClip(pendingClips.removeAt(0))
        } else audioPath?.let { play(it) }
    }

    /** Queue a synthesized sentence clip; start it when nothing is playing. */
    private fun enqueueClip(path: String) {
        if (mediaBase == null) return
        pendingClips.add(path)
        if (player == null) startClip(pendingClips.removeAt(0))
    }

    // ---- touch -----------------------------------------------------------------------------
    override fun onTap(x: Float, y: Float, cx: Float, cy: Float, r: Float, page: Int): Boolean {
        val f = r / 240f
        if (confirmToken.isNotEmpty()) {
            val by = cy + 142f * f
            val yes = hypot(x - (cx + 72f * f), y - by) < 38f * f
            val no = hypot(x - (cx - 72f * f), y - by) < 38f * f
            val always = hypot(x - cx, y - (cy + 190f * f)) < 30f * f
            if (yes || no || always) {
                send(JSONObject().put("ch", "assistant")
                    .put("data", op("confirm") {
                        it.put("token", confirmToken).put("yes", yes || always).put("always", always)
                    }))
                confirmToken = ""
                confirmAudioPath = null
                resetAudio()
                status = "Running…"
                invalidate()
                return true
            }
        } else if (streamToken.isNotEmpty() && hypot(x - cx, y - (cy + 158f * f)) < 40f * f) {
            send(JSONObject().put("ch", "assistant").put("data", op("cancel") { it.put("token", streamToken) }))
            status = "Cancelling…"
            invalidate()
            return true
        } else if (audioPath != null && abs(y - cy) < 70f * f) {
            replayAudio()     // tap the answer to hear the whole reply again
            return true
        }
        return true
    }

    // ---- drawing ---------------------------------------------------------------------------
    override fun draw(c: Canvas, cx: Float, cy: Float, r: Float, f: Float, page: Int, ambient: Boolean) {
        val sub = if (confirmToken.isNotEmpty()) "approval"
                  else deviceName.take(20).ifEmpty { "your assistant" }
        Draw.header(c, cx, cy, f, "Jarvis", sub, color)

        var y = cy - 124f * f
        if (prompt.isNotEmpty()) {
            y = wrap(c, "You: " + prompt, cx - r * 0.70f, y, r * 1.40f, 14f * f, Draw.mutedColor) + 14f * f
        }
        if (status.isNotEmpty()) {
            y = wrap(c, status, cx - r * 0.70f, y, r * 1.40f, 17f * f,
                if (confirmToken.isNotEmpty()) Draw.ramColor else color) + 14f * f
        }
        if (steps.isNotEmpty()) {
            val text = steps.joinToString("  ·  ") { if (it.done) "✓ ${it.name}" else it.name }
            y = wrap(c, text, cx - r * 0.70f, y, r * 1.40f, 12f * f, Draw.gridColor) + 12f * f
        }
        if (reply.isNotEmpty()) {
            wrap(c, reply, cx - r * 0.70f, y, r * 1.40f, 20f * f, Draw.textColor, 8)
        } else if (confirmText.isNotEmpty()) {
            wrap(c, confirmText, cx - r * 0.70f, y + 6f * f, r * 1.40f, 18f * f, Draw.textColor, 5)
        } else if (reply.isEmpty() && status.isEmpty()) {
            Draw.ring.strokeWidth = 5f * f; Draw.ring.color = color
            c.drawCircle(cx, cy - 34f * f, 44f * f, Draw.ring)
            Draw.line.strokeWidth = 5f * f; Draw.line.color = color
            c.drawLine(cx, cy - 34f * f, cx, cy - 6f * f, Draw.line)
            Draw.fill.color = color; Draw.fill.alpha = 255
            c.drawCircle(cx, cy - 60f * f, 5f * f, Draw.fill)
            wrap(c, "tap the Voice face and choose Jarvis", cx - r * 0.68f, cy + 42f * f,
                r * 1.36f, 13f * f, Draw.mutedColor, 2)
        }

        if (confirmToken.isNotEmpty()) {
            val by = cy + 142f * f
            drawPill(c, cx - 72f * f, by, 58f * f, "No", Draw.dimColor)
            drawPill(c, cx + 72f * f, by, 58f * f, "Yes", color)
            drawPill(c, cx, cy + 190f * f, 44f * f, "Always", Draw.gridColor)
        } else if (streamToken.isNotEmpty()) {
            drawPill(c, cx, cy + 158f * f, 46f * f, "Stop", Draw.dimColor)
        } else if (reply.isNotEmpty() && audioPath != null) {
            Draw.label(c, "tap to replay", cx, cy + 158f * f, 10f * f, Draw.gridColor)
        }
    }

    /** Minimal word wrap; returns the y after the last line. */
    private fun wrap(c: Canvas, text: String, x: Float, y0: Float, width: Float,
                     size: Float, col: Int, maxLines: Int = 10): Float {
        Draw.text.textSize = size
        Draw.text.color = col
        Draw.text.textAlign = Paint.Align.LEFT
        Draw.text.typeface = android.graphics.Typeface.DEFAULT
        var y = y0
        var rest = text.trim()
        var lines = 0
        while (rest.isNotEmpty() && lines < maxLines) {
            val count = Draw.text.breakText(rest, true, width, null)
            if (count <= 0) break
            val line = rest.substring(0, count)
            c.drawText(line, x, y, Draw.text)
            rest = rest.substring(count).trim()
            y += size * 1.28f
            lines++
        }
        return y
    }

    private fun drawPill(c: Canvas, x: Float, y: Float, halfW: Float, label: String, bg: Int) {
        Draw.fill.color = bg; Draw.fill.alpha = 255
        c.drawRoundRect(x - halfW, y - 24f, x + halfW, y + 24f, 24f, 24f, Draw.fill)
        Draw.label(c, label, x, y + 6f, 16f, if (bg == color) Color.BLACK else Draw.textColor, bold = true)
    }

    override fun drawIcon(c: Canvas, x: Float, y: Float, size: Float, selected: Boolean) {
        val col = if (selected) color else Draw.mutedColor
        Draw.ring.strokeWidth = size * 0.08f; Draw.ring.color = col
        c.drawCircle(x, y, size * 0.38f, Draw.ring)
        Draw.line.strokeWidth = size * 0.07f; Draw.line.color = col
        c.drawLine(x - size * 0.14f, y + size * 0.10f, x - size * 0.24f, y + size * 0.34f, Draw.line)
        Draw.fill.color = col; Draw.fill.alpha = 255
        c.drawCircle(x - size * 0.12f, y, size * 0.04f, Draw.fill)
        c.drawCircle(x + size * 0.12f, y, size * 0.04f, Draw.fill)
        Draw.label(c, "•", x, y + size * 0.08f, size * 0.24f, col)
    }

    companion object {
        private const val TAG = "EchoPortal.Assistant"
        private const val MAX_REPLY_CHARS = 600
    }
}
